const items=[{"category": "sports", "image": "kim-02-ssireum.png", "src": "assets/images/about-rebuild/archive/02-ssireum.webp", "title": "씨름", "body": "두 사람이 힘을 겨루는 동안 관중들은 둘러앉아 승부를 지켜본다.", "en": "Spectators gather around two wrestlers and follow the match.", "actions": "GATHER / ENJOY", "year": 1750, "tags": ["sports", "daily"], "crop": "56% 54%"}, {"category": "pop", "image": "kim-03-mudong.png", "src": "assets/images/about-rebuild/archive/03-mudong.webp", "title": "무동", "body": "악사들의 연주에 맞춰 아이가 춤을 춘다. 소리와 몸짓이 한 장면 안에서 어우러진다.", "en": "Musicians play as a child dances, bringing sound and movement together.", "actions": "PLAY / ENJOY", "year": 1750, "tags": ["festival", "daily", "pop"], "crop": "43% 50%"}, {"category": "daily", "image": "kim-01-seodang.png", "src": "assets/images/about-rebuild/archive/01-seodang.webp", "title": "서당", "body": "훈장과 아이들이 한자리에 모여 배우는 일상이 담겨 있다.", "en": "A teacher and children share the space of a village school.", "actions": "LEARN / GATHER", "year": 1750, "tags": ["daily"], "crop": "50% 50%"}, {"category": "daily", "image": "kim-04-daejanggan.png", "src": "assets/images/about-rebuild/archive/04-daejanggan.webp", "title": "대장간", "body": "쇠를 두드리고 불을 지피는 사람들이 작업을 나누어 맡는다.", "en": "Workers tend the fire and hammer iron, each contributing to the work.", "actions": "WORK TOGETHER", "year": 1750, "tags": ["daily"], "crop": "50% 50%"}, {"category": "food", "image": "kim-05-jumak.png", "src": "assets/images/about-rebuild/archive/05-jumak.webp", "title": "주막", "body": "음식을 내는 사람과 식사하는 사람이 주막에서 마주한다.", "en": "Serving and eating bring people together in a tavern.", "actions": "SHARE / MEET", "year": 1750, "tags": ["food", "daily"], "crop": "50% 50%"}, {"category": "daily", "image": "kim-06-bbalraeteo.png", "src": "assets/images/about-rebuild/archive/06-bbalraeteo.webp", "title": "빨래터", "body": "물가에서 빨래하는 사람들의 서로 다른 몸짓이 한 장면을 이룬다.", "en": "People wash clothes by the water, sharing a place of everyday work.", "actions": "WORK / GATHER", "year": 1750, "tags": ["daily"], "crop": "50% 50%"}, {"category": "daily", "image": "kim-07-byeotajak.png", "src": "assets/images/about-rebuild/archive/07-byeotajak.webp", "title": "벼타작", "body": "수확한 벼를 타작하는 사람들이 각자의 움직임으로 일을 이어간다.", "en": "People thresh harvested rice, each taking part in the work.", "actions": "WORK TOGETHER", "year": 1750, "tags": ["daily"], "crop": "50% 50%"}, {"category": "daily", "image": "kim-08-gonunori.png", "src": "assets/images/about-rebuild/archive/08-gonunori.webp", "title": "고누놀이", "body": "놀이를 하는 사람과 지켜보는 사람들이 고누판을 중심으로 모인다.", "en": "Players and onlookers gather around a game of gonu.", "actions": "PLAY / GATHER", "year": 1750, "tags": ["daily"], "crop": "50% 50%"}, {"category": "daily", "image": "kim-09-narutbae.png", "src": "assets/images/about-rebuild/archive/09-narutbae.webp", "title": "나룻배", "body": "여러 사람이 한 배에 올라 같은 강을 건넌다.", "en": "Different people share a boat as they cross the river.", "actions": "TRAVEL / SHARE", "year": 1750, "tags": ["daily"], "crop": "50% 50%"}, {"category": "food", "image": "kim-10-jeomsim.png", "src": "assets/images/about-rebuild/archive/10-jeomsim.webp", "title": "점심", "body": "일을 잠시 멈춘 사람들이 모여 앉아 식사하고 쉰다.", "en": "People pause their work to eat and rest together.", "actions": "SHARE / REST", "year": 1750, "tags": ["food", "daily"], "crop": "50% 50%"}, {"category": "daily", "image": "ox-market-1904.jpg", "title": "장터에 모인 사람들", "body": "1904년경 우시장의 모습을 담은 엽서다. 사람과 가축이 모인 장터에서 당시 교류의 공간을 볼 수 있다.", "en": "A postcard records people and livestock gathering at an ox market around 1904.", "actions": "TRADE / GATHER", "tags": ["daily"], "year": 1904, "crop": "50% 50%"}, {"category": "sports", "image": "193726851.jpg", "title": "하나의 응원으로 모이다", "body": "같은 경기를 지켜보는 사람들이 구호와 환호를 나누며 광장을 채운다.", "en": "Gathering through shared support and excitement.", "actions": "GATHER / ENJOY", "tags": ["sports"], "year": 2026, "crop": "50% 50%"}, {"category": "food", "image": "bapsang-2013.jpg", "title": "한 상에 놓인 음식들", "body": "밥과 국, 여러 반찬이 한 상에 놓여 있다. 식탁을 중심으로 이어지는 일상의 기록이다.", "en": "Rice, soup and side dishes arranged on a Korean meal table.", "actions": "SHARE / DAILY LIFE", "tags": ["food"], "year": 2013, "crop": "50% 65%"}, {"category": "pop", "image": "79503095.jpg", "title": "같은 노래를 함께 듣다", "body": "무대와 관객석이 노래로 이어지고, 서로 다른 자리의 사람들이 한 공연을 함께한다.", "en": "One performance, shared across the crowd.", "actions": "GATHER / ENJOY", "tags": ["pop"], "year": 2019, "crop": "50% 58%"}, {"category": "festival", "image": "132770131.jpg", "title": "연등을 따라 걷다", "body": "저마다 든 연등이 긴 행렬을 이루고, 사람들은 같은 길을 함께 걷는다.", "en": "Individual lanterns becoming a shared procession.", "actions": "GATHER", "tags": ["festival"], "year": 2023, "crop": "50% 50%"}, {"category": "daily", "image": "149376627.jpg", "title": "장기판 곁에 머물다", "body": "두 사람이 두는 장기를 주변 사람들이 함께 지켜보며 한자리에 머문다.", "en": "A game becoming a place to gather.", "actions": "GATHER / ENJOY", "tags": ["daily"], "year": 2024}, {"category": "pop", "image": "78410547.jpg", "title": "같은 무대에 답하다", "body": "팬들은 응원봉을 들고 같은 무대를 바라보며 공연의 순간을 나눈다.", "en": "Responding to a performance together.", "actions": "GATHER / ENJOY", "tags": ["pop"], "year": 2018, "crop": "50% 50%"}, {"category": "sports", "image": "52819731.jpg", "title": "관중석을 채우는 응원", "body": "같은 팀을 바라보는 관중들이 경기의 흐름에 함께 반응한다.", "en": "Following the game from a shared stand.", "actions": "GATHER / ENJOY", "tags": ["sports"], "year": 2014, "crop": "48% 65%"}, {"category": "pop", "image": "blackpink-coachella-2023", "title": "무대에 함께 답하는 순간", "body": "2023년 코첼라 무대에 선 블랙핑크. 노래와 춤에 관객이 함께 호응하는 K-pop 공연의 장면이다.", "en": "BLACKPINK at Coachella in 2023, sharing a performance with the audience.", "actions": "MAKE TOGETHER / GATHER", "tags": ["pop"], "year": 2023, "crop": "50% 50%", "src": "assets/images/phone-editorial-20261105/blackpink-coachella-2023.jpg"}, {"category": "food", "image": "54573735.jpg", "title": "먹거리를 함께 준비하다", "body": "여러 사람이 배추를 손질하며 김장에 필요한 일을 나누어 한다.", "en": "Dividing the work of preparing food.", "actions": "MAKE TOGETHER", "tags": ["food"], "year": 2016, "crop": "50% 40%"}, {"category": "daily", "image": "31701599.jpg", "title": "윷이 떨어질 때마다", "body": "마당의 윷놀이를 둘러싼 사람들이 차례를 기다리고 놀이를 함께 지켜본다.", "en": "Taking turns and watching a game together.", "actions": "GATHER / ENJOY", "tags": ["daily"], "year": 2013, "crop": "50% 50%"}, {"category": "pop", "image": "31716398.jpg", "title": "함께 맞추는 움직임", "body": "K-POP을 함께 추는 사람들이 음악에 맞춰 동작과 호흡을 맞춘다.", "en": "Moving to the same music together.", "actions": "MAKE TOGETHER / ENJOY", "tags": ["pop"], "year": 2012, "crop": "50% 50%"}, {"category": "sports", "image": "64198806.jpg", "title": "응원을 이어 부르다", "body": "야구장의 사람들이 같은 경기를 보며 응원과 환호에 함께 참여한다.", "en": "Joining the cheers around a game.", "actions": "GATHER / ENJOY", "tags": ["sports"], "year": 2017, "crop": "50% 60%"}, {"category": "food", "image": "7281038.jpg", "title": "골목에서 나누는 한 끼", "body": "같은 상에 둘러앉은 사람들이 음식을 먹으며 식사의 시간을 함께한다.", "en": "Sharing a meal at the same table.", "actions": "SHARE / GATHER", "tags": ["food"], "year": 2007, "crop": "50% 50%"}, {"category": "festival", "image": "31712042.jpg", "title": "손을 잡고 원을 이루다", "body": "강강술래에 참여한 사람들이 손을 잇고 서로의 움직임에 맞춰 원을 이룬다.", "en": "Holding hands and moving as a circle.", "actions": "MAKE TOGETHER / ENJOY", "tags": ["festival"], "year": 2013, "crop": "50% 50%"}, {"image": "street-vendors-1950.jpg", "category": "daily", "title": "거리에서 이어지는 일상", "body": "1950년경 거리의 상인과 오가는 사람들을 담은 기록이다.", "en": "Street vendors and passers-by share a street in Korea, circa 1950.", "year": 1950, "actions": "TRADE / MEET", "tags": ["daily"], "crop": "50% 50%"}, {"image": "seoul-olympics-1988.jpg", "category": "sports", "title": "서울올림픽 개회식의 한 장면", "body": "1988년 서울올림픽 개회식에서 깃발을 든 참여자의 모습을 담은 기록이다.", "en": "A flag bearer takes part in the opening ceremony of the 1988 Seoul Olympics.", "year": 1988, "actions": "GATHER / CEREMONY", "tags": ["sports"], "crop": "50% 50%"}, {"image": "kim-wansun-stage-2012.jpg", "category": "pop", "tags": ["pop"], "year": 2012, "title": "빛과 리듬 속의 무대", "body": "2012년 여수엑스포 팝 페스티벌에서 공연하는 김완선. 노래와 춤이 관객에게 전해지는 무대의 순간이다.", "en": "Kim Wan-sun performing at the 2012 Yeosu Expo Pop Festival.", "actions": "SING / DANCE", "crop": "50% 55%"}, {"image": "editorial-kfood-01", "src": "assets/images/phone-editorial-20261105/kfood-01.jpg", "category": "food", "year": 2025, "title": "한 테이블에 모인 취향", "body": "떡볶이부터 김밥까지, 먹고 싶은 메뉴 하나씩 골라 같이 놓기.", "en": "Everyone picks a favorite. One table, plenty to share.", "actions": "SHARE / GATHER", "tags": ["food"], "crop": "50% 50%"}, {"image": "editorial-kfood-02", "src": "assets/images/phone-editorial-20261105/kfood-02.jpg", "category": "food", "year": 2024, "title": "같이 굽고 나누는 저녁", "body": "잘 구워진 한 점은 옆 사람 접시부터. 같이 먹을 때 더 맛있는 저녁.", "en": "The first bite goes to the person beside you. Dinner tastes better shared.", "actions": "MAKE TOGETHER / SHARE", "tags": ["food"], "crop": "50% 50%"}, {"image": "editorial-ksports-01", "src": "assets/images/phone-editorial-20261105/ksports-01.jpg", "category": "sports", "year": 2022, "title": "관중석을 채운 같은 마음", "body": "경기장에 울리는 함성. 옆자리와 같은 순간에 일어나 응원하기.", "en": "Getting to our feet at the same moment, cheering alongside strangers.", "actions": "GATHER / ENJOY", "tags": ["sports"], "crop": "50% 50%"}, {"image": "editorial-ksports-02", "src": "assets/images/phone-editorial-20261105/ksports-02.jpg", "category": "sports", "year": 2022, "title": "오늘은 야구장", "body": "그라운드가 한눈에 보이는 자리. 응원가 따라 부르며 보내는 오후.", "en": "An open view of the field, and an afternoon singing along from the stands.", "actions": "GATHER / ENJOY", "tags": ["sports"], "crop": "50% 50%"}, {"image": "editorial-kfestival-01", "src": "assets/images/phone-editorial-20261105/kfestival-01.jpg", "category": "festival", "year": 2026, "title": "등 아래 잠깐의 산책", "body": "머리 위로 이어지는 등을 따라 천천히 걷기. 함께 보고 싶은 풍경.", "en": "Following rows of lanterns. A view worth sharing.", "actions": "GATHER / ENJOY", "tags": ["festival"], "crop": "50% 50%"}, {"image": "editorial-kfestival-02", "src": "assets/images/phone-editorial-20261105/kfestival-02.jpg", "category": "festival", "year": 2020, "title": "같은 하늘을 보는 밤", "body": "불꽃이 피는 순간 같이 고개를 들었다. 사진보다 오래 남는 장면.", "en": "We looked up together as the fireworks opened. A moment that outlasts the photo.", "actions": "GATHER / ENJOY", "tags": ["festival"], "crop": "50% 50%"}, {"image": "editorial-market-seoul", "src": "assets/images/phone-editorial-20261105/market-seoul.jpg", "category": "daily", "year": 2025, "title": "광장시장에서 마주치는 일상", "body": "한글 간판과 가게들이 이어진 시장 골목에서 사람들의 일상이 교차한다.", "en": "Everyday paths meet among the signs and stalls of Gwangjang Market.", "actions": "MEET / SHARE", "tags": ["daily", "food"], "crop": "50% 50%"}];
